mapper.select:
SELECT 
FROM vso_order t
WHERE t.row_valid = 1

    AND t.id = #{id}


    AND t.order_id = #{orderId}


    AND t.order_no = #{orderNo}


    AND t.order_type = #{orderType}


    AND t.order_source = #{orderSource}


    AND t.customer_type = #{customerType}


    AND t.order_state = #{orderState}


    AND t.brand_code = #{brandCode}


    AND t.owner_region_code = #{ownerRegionCode}


    AND t.order_store_code = #{orderStoreCode}


    AND t.owner_store_code = #{ownerStoreCode}


    AND t.delivery_store_code = #{deliveryStoreCode}


    AND t.delivery_region_code = #{deliveryRegionCode}


    AND t.sales_code = #{salesCode}


    AND t.vehicle_vin = #{vehicleVin}


    AND t.create_time = #{createTime}


    AND t.create_by = #{createBy}


    AND t.modify_time = #{modifyTime}


    AND t.modify_by = #{modifyBy}


    AND t.row_version = #{rowVersion}

ORDER BY t.id DESC

SELECT 
FROM vso_order t
WHERE t.row_valid = 1

    AND EXISTS (
        SELECT 1 FROM vso_order_party p
        WHERE p.order_id = t.order_id AND p.user_id = #{accountId}
        AND p.party_role = 'order_user' AND p.row_valid = 1
    )


    AND t.delivery_person_id IS NOT NULL AND t.delivery_person_id != ''


    AND (t.delivery_person_id IS NULL OR t.delivery_person_id = '')


    AND t.order_state = #{orderState}


    AND t.order_state IN

        #{status}



    AND t.order_no = #{orderNo}


    AND t.order_store_code = #{orderStoreCode}


    AND t.owner_store_code = #{ownerStoreCode}


    AND t.sales_code = #{salesCode}


    AND t.created_at_business >= #{beginTime}


    AND t.created_at_business <= #{endTime}

ORDER BY t.id DESC

SELECT COUNT(*)
FROM vso_order t
WHERE t.row_valid = 1

    AND t.sale_model = #{saleModel}


    AND t.order_state = #{orderState}


    AND t.order_state IN

        #{status}



    AND t.delivery_person_id = #{deliveryPersonId}




            AND t.delivery_finish_time IS NOT NULL


            AND t.delivery_finish_time IS NULL

SELECT t.delivery_person_id AS deliveryPersonId, COUNT(*) AS orderCount FROM vso_order t WHERE t.row_valid = 1 AND t.delivery_person_id IN
#{deliveryPersonId}
AND t.delivery_finish_time IS NULL GROUP BY t.delivery_person_id

SELECT 
FROM vso_order t
WHERE t.order_no = #{orderNo}
AND t.row_valid = 1
AND EXISTS (
    SELECT 1 FROM vso_order_party p
    WHERE p.order_id = t.order_id AND p.user_id = #{accountId}
    AND p.party_role = 'order_user' AND p.row_valid = 1
)

SELECT 
FROM vso_order t
WHERE t.order_id = #{orderId}
AND t.row_valid = 1
AND EXISTS (
    SELECT 1 FROM vso_order_party p
    WHERE p.order_id = t.order_id AND p.user_id = #{accountId}
    AND p.party_role = 'order_user' AND p.row_valid = 1
)

SELECT 
FROM vso_order t
WHERE t.row_valid = 1
AND t.order_state = #{orderState}
AND t.down_payment_time IS NOT NULL
AND t.down_payment_time <= #{deadline}
ORDER BY t.down_payment_time ASC
LIMIT #{limit}

